  catVillage: {
    title: "猫猫村布告牌",
    commissionListTitle: "委托",
    commissionCountSuffix: "个",
    reputation: "猫村声望",
    refresh: "刷新",
    refreshCommission: "换一个",
    deleteCommission: "放弃",
    confirmDelete: "确认放弃这个委托吗？",
    maxLevel: "已满级",
    totalReputation: "累计声望",
    refreshCostHint: "花费 {cost} 换一个新委托（每个委托只能换一次）",
    tabLife: "生活委托",
    tabBattle: "战斗委托",
    commission: {
      cvc_toyshop_wood: { name: "木匠铺的托付", desc: "几只小猫围在木匠铺门口，眼巴巴地看着架子上的小木剑。木匠猫说，只要有人送来些木头，顺手就能多做几把。" },
      cvc_bakery_firewood: { name: "面包坊急需柴火", desc: "面包坊的橱窗里摆着金黄的面包，但灶台快熄了。老板猫把胡子一撸，说今天的松软麻花要靠你了。" },
      cvc_morning_eggs: { name: "早市的新鲜鸡蛋", desc: "清晨的集市刚开张，蛋糕铺的老板娘正急得团团转——今天的订单里少了一篮鸡蛋，求猫猫们帮帮忙。" },
      cvc_cafe_milk: { name: "拿铁猫咖的牛奶", desc: "\"拿铁猫咖\"的招牌奶泡快用完了，调酒师猫正愁眉苦脸地盯着空瓶，说今天的特调要缺货了。" },
      cvc_tailor_wool: { name: "裁缝铺的绒线货", desc: "裁缝铺的橱窗里挂着半件毛衣，顾客已经等了三天。老裁缝猫急忙拦住路过的你，说原料短缺，需要一批羊毛。" },
      cvc_well_stone: { name: "修缮村口旧井", desc: "村口那口古井的井沿开裂了，村民们打水总要小心翼翼。村长猫指着石料摊说，你若能带来些石头，明天就能修好。" },
      cvc_road_stone: { name: "主街道铺路", desc: "下了雨的泥路溅了好几只猫一身，市政猫皱着眉头，说铺路石备得不够，铺到一半就断了。" },
      cvc_sap_pharmacy: { name: "药铺的树脂原料", desc: "药铺老板一边捣药一边念叨，说树脂补货晚了三天，好几种膏药都停产了，你来得正是时候。" },
      cvc_dew_garden: { name: "花圃猫要晨露", desc: "花圃里的玻璃瓶整整齐齐排成一排，花匠猫每天天亮前都要去采，但最近腿伤了，晨露只好拜托旁人了。" },
      cvc_flax_weaver: { name: "纺织社补货", desc: "纺织社门口贴着\"原料告急\"的告示，社长猫站在门边问有没有人能送些麻纤维来，说工坊已经停机半天了。" },
      cvc_coal_kitchen: { name: "食堂要炭火", desc: "村子公共食堂的灶火越来越小，大厨猫不停往里加炭，说炭火不够，中午的鱼汤要冷着上了。" },
      cvc_copper_tools: { name: "工具铺备料", desc: "工具铺的铁锤和凿子卖断货了，铁匠猫对着空架子发愁，说铜矿存货不足，下批货要等好几天。" },
      cvc_fence_wood: { name: "围栏破了个口", desc: "最近有只野猫经常从围栏缺口溜进来偷菜，农夫猫正皱着眉头盯着缺口，说木头不够，补不上。" },
      cvc_bridge_stone: { name: "小桥踏石松了", desc: "村口小桥有两块踏脚石松动了，每次过桥都「咕噔」一响。负责维修的猫说你若能送些石头来，今天就能修好。" },
      cvc_candle_sap: { name: "蜡烛坊缺树脂", desc: "蜡烛坊架子上的蜡烛卖得七七八八，老板猫说树脂原料不够，今晚村里好几户的灯要暗着。" },
      cvc_market_dew: { name: "香露摊缺货了", desc: "集市上有个专卖香露的小摊，摊主猫说今天早起晚了没采到够量，还差一些晨露，急着补。" },
      cvc_henhouse_eggs: { name: "养鸡场的日供缺口", desc: "养鸡场今天出了点意外，一批鸡蛋打碎了，场主猫急着向外收购补上今天的订单缺口。" },
      cvc_cheese_milk: { name: "奶酪坊重新备货", desc: "奶酪坊里刚好几缸奶酪腌坏了，老板猫叹着气说，要重新做一批，得先补上原料才行。" },
      cvc_blanket_wool: { name: "冬被工坊提前备料", desc: "冬被工坊已经开始提前备料，工坊主猫说每年都等到天冷才找材料，今年要提前行动，省得手忙脚乱。" },
      cvc_lumber_new_house: { name: "新屋打桩备木料", desc: "村里一对年轻猫刚买了块地基，正要盖新屋，木料还差一截，向外求购，价格公道。" },
      cvc_gravel_garden: { name: "菜园铺碎石走道", desc: "花园猫说在菜畦旁铺上碎石走道，下雨就不会踩一脚泥，但石头还缺着，你帮个忙？" },
      cvc_morning_nectar: { name: "蜜铺的每日采购", desc: "蜜铺每天一开门就用完前日存货，今天一早就来采购了，老板猫说量不多，快点的话还赶得上。" },
      cvc_coal_forge_daily: { name: "铸造室补炭", desc: "铸造室的炉火每天都在消耗，今天采矿队拉货晚了，只剩半桶炭，先在村里收购顶上。" },
      cvc_fiber_combo_light: { name: "纺织小组轻量任务", desc: "纺织小组今天要赶一批轻薄布料的订单，麻纤维或者棉纤维都行，你有哪种方便带哪种。" },
      cvc_bookshelf_sturdy: { name: "图书馆要新书架", desc: "村子图书馆终于要扩建了，管理员猫欢欣鼓舞地说要做新书架，但硬木还差一点，求购。" },
      cvc_bridge_combo: { name: "新桥关键工程", desc: "新桥建造进入关键阶段，工头猫说根据当天的施工安排，今天需要的材料不一样，哪种先到就先用。" },
      cvc_medicine_combo: { name: "药坊综合进货", desc: "药坊库存了三种急需原料，老大夫说哪种都有用，先送哪种来，他先调配哪种药，不挑。" },
      cvc_kitchen_combo: { name: "大厨房综合备料", desc: "大厨房同时要备炉火和食材，采购猫列了三种方案，说哪种先到手就先干哪项，不用等齐。" },
      cvc_iron_cotton_combo: { name: "工业坊双需委托", desc: "工业坊同时接了铸件和布料两项任务，采购猫说这两种材料同时要，一并送来最省事。" },
      cvc_wool_milk_combo: { name: "牧场联合供应", desc: "牧场合作社说两种产品都有订单，联合委托一次送齐，双份报酬，今天有效。" },
      cvc_building_foundation: { name: "楼房地基双材", desc: "村子在建的三层楼房地基工程需要大量石料，外加烧制水泥用的炭火，今天要一并采购。" },
      cvc_fiber_bulk_combo: { name: "布业公会联合补货", desc: "布业公会集体开会决定联合补货，三种纤维材料择一大批进货，今天要敲定，先到先得。" },
      cvc_copper_sap_combo: { name: "工艺坊混合进料", desc: "工艺坊要做新一批铜制器皿，器皿表面还要上一层树脂漆，两种原料今天同时采购。" },
      cvc_forge_mid: { name: "铸造坊中级备料", desc: "铸造坊接了两种不同类型的订单，根据今天的工序安排，需要不同组合的原料，先到哪组就先干。" },
      cvc_silverleaf_sap_craft: { name: "银叶精工坊特制品", desc: "银叶精工坊要做一批特殊木制品，需要银叶木为主体，外加普通树脂做填料，两种都要。" },
      cvc_temple_ceremony: { name: "神殿香祀大典备料", desc: "神殿正在筹备一年一度的香祀大典，需要银叶香木供奉，还需雕刻石刻制祭祀铭牌，缺一不可。" },
      cvc_luxury_combo: { name: "贵族礼服联合订单", desc: "贵族订单要求用银叶纤维制礼服、银叶晨露作香料，两种都要，报酬丰厚，时间不等人。" },
      cvc_rare_fiber_combo: { name: "稀有纤维两选一", desc: "高端纺织坊正在等两种稀有纤维中的一种，哪种先到就先开工，价格一样好，不挑。" },
      cvc_alchemy_combo: { name: "灌注双配方", desc: "灌注工坊今天有两种配方待制，根据最先到货的原料来决定先做哪种，你选一组送来就行。" },
      cvc_scholar_rare: { name: "学者的稀材研究请求", desc: "学者猫在研究一种失传的工艺，需要从稀有材料入手，三种各有用处，先送哪种来就先研究哪条路。" },
      cvc_silver_engrave_combo: { name: "银刻坊联合订单", desc: "银刻坊正在赶制一批纪念章，银矿用来铸坯，雕刻石用来打磨，两种材料都急需，一并送来最好。" },
      cvc_silkweed_sap_craft: { name: "丝草精工坊特制品", desc: "丝草工坊接了一笔精品订单，需要丝草纤维和树脂配合使用，两种原料同时告急。" },
      cvc_silkwood_gold_combo: { name: "顶级工坊王室双料", desc: "顶级工坊接了一笔王室订单，要用丝木打骨架、黄金矿石镀表面，两种都不能少，今日委托。" },
      cvc_moonwood_moonvine: { name: "月系器具特别委托", desc: "月树工坊正在赶制一套月光系列器具，需要月木和月藤纤维同时到货才能开工，急！" },
      cvc_golden_textile: { name: "金色混纺顶级布料", desc: "金色纺织坊接了一批出口订单，要用金藤纤维和丝草纤维混纺，两种都要，货源紧俏。" },
      cvc_vault_max: { name: "金库年度联合补仓", desc: "金库本周进行年度盘点，银矿和金矿同时告急，联合采购，报酬翻倍，今日有效。" },
      cvc_moon_dew_essence_combo: { name: "月华秘宝双品同求", desc: "秘宝研究所的研究猫同时需要月华之露和月光精华，两种都是珍稀材料，同时到货有额外加成。" },
      cvc_goldvine_moonwood_combo: { name: "金月双宝极品委托", desc: "极品工艺馆说金藤和月木搭配在一起才能做出最顶级的制品，这是今年最后一单此类委托。" },
      cvc_moon_essence_combo: { name: "月华秘药特别配方", desc: "月华药坊的秘方需要月光精华和软树脂同时使用，缺一不可，今天的委托限量发放。" },
      cvc_silkweed_nectar_guild: { name: "丝草蜜的稀有订单", desc: "顶级蜜坊说只有丝草的花蜜才能调配出最高档的蜂蜜制品，市面上极少见，全价收购。" },
      cvc_sunlit_nectar_rare: { name: "阳光花蜜的委托", desc: "一家高档点心铺的老板猫说阳光花蜜是秘制糕点的点睛之笔，特地发出高价委托，求一些货来。" },
      cvc_moon_resin_lab: { name: "实验室要月树脂", desc: "实验室的研究猫手边的月树脂已经不够用了，他戴着护目镜抬起头说，没有月树脂今天的实验就停了。" },
      cvc_furniture_sturdy: { name: "家具坊的硬木料", desc: "村子里最好的木匠老爷爷猫正在做一套婚礼桌椅，但硬木快用完了，他搓着爪子说，再不到货，婚礼就要推迟了。" },
      cvc_dock_sturdy: { name: "渡口修船", desc: "渡口的摆渡船底板开裂了，船夫猫把货都挪上了岸，说没有硬木就无法出航，货主已经在催了。" },
      cvc_iron_smithy: { name: "铁匠铺的铁矿", desc: "铁匠猫正盯着冷却的锻造台，说上批铁矿刚用光，新批兵器的订单还在等，谁能送矿谁就是救星。" },
      cvc_cotton_mill: { name: "棉布坊补棉料", desc: "棉布坊门口挂着布样，老板猫说秋季新款刚出图纸，但棉纤维进货跟不上，新款得往后延。" },
      cvc_soft_resin_apothecary: { name: "大夫要软树脂", desc: "药铺里几罐跌打膏药只剩底了，老大夫猫翻着方子说软树脂是主料，没它膏药就调不出来。" },
      cvc_nectar_brewery: { name: "酿蜜工坊的甜蜜蜜", desc: "酿蜜工坊飘着香甜气息，但调配师猫皱着眉头说，今年花蜜收成差，工坊的最新配方缺了关键原料。" },
      cvc_dairy_bulk: { name: "乳品坊的大批订单", desc: "乳品坊接到了一笔大订单，老板猫戴着围裙忙进忙出，说这个月的牛奶收购量要翻倍，欢迎各位多送。" },
      cvc_harvest_combo: { name: "秋收联合收购", desc: "收购站贴出了联合采购的告示，说养殖坊同时需要鸡蛋和羊毛，一起送来的话还能多给点报酬。" },
      cvc_village_prep_basic: { name: "猫猫村日常筹备", desc: "村子公告栏贴着一张长长的采购清单，收购员猫说无论你带来哪种基础物资，今天都缺，先到先得。" },
      cvc_inn_combo: { name: "客栈综合供给", desc: "客栈老板娘猫同时接了好几桌订单，仓库里东缺一样西缺一样，你有什么带什么，能凑上一组就行。" },
      cvc_coal_winter_stock: { name: "矿场的冬储煤炭", desc: "村子里的冬储计划已经开始，矿场管理猫说要趁现在多收一批煤炭，省得入冬措手不及。" },
      cvc_warehouse_stone: { name: "新建仓库的石料", desc: "村长猫拿着建筑图纸比划，说新仓库的地基需要大量石料，这批若能备齐，工期就能如期开工。" },
      cvc_workshop_combo: { name: "工坊综合备料", desc: "工坊里的项目表排得满满当当，采购猫说材料清单每天都在变，你带哪一组来，他就先干哪个活。" },
      cvc_village_prep_mid: { name: "猫猫村中期筹备", desc: "村子扩建进度到了中期，管理委员会列出了一批中等材料需求，谁能送货谁就是今天的贡献猫。" },
      cvc_temple_silverleaf: { name: "神殿的银叶香木", desc: "神殿猫正在清点香炉旁的供品，说近来祈愿的猫越来越多，银叶木的香料有些供不应求了。" },
      cvc_luxury_silverleaf_fiber: { name: "银叶绸坊的定制料", desc: "绸坊老板取下架子上的布样，悄声说贵族订的礼服就等这批银叶纤维，交货期快到了，价格好商量。" },
      cvc_jeweler_silver: { name: "珠宝坊的银矿原料", desc: "珠宝铺里摆着半成品的银项圈，工匠猫戴着放大镜说，银矿库存见底了，好几件订单都卡着，急！" },
      cvc_alchemy_silverleaf_resin: { name: "炼金室的银叶树脂", desc: "炼金师猫在烧瓶旁抬起头，神秘兮兮地说银叶树脂是某个秘方的关键，外头很少有存货，来一点是一点。" },
      cvc_silverleaf_dew_perfumer: { name: "调香师要银叶晨露", desc: "调香师猫对着一只空瓶发愁，说银叶晨露只能清晨采，产量太少，委托能多带点来最好。" },
      cvc_clear_resin_workshop: { name: "高端工坊要纯净树脂", desc: "高端工坊的品控猫挑剔地检查每一批材料，说普通树脂不合格，只收纯净品，价格随行就市。" },
      cvc_sculptor_engrave_stone: { name: "雕刻大师的原料", desc: "雕刻大师猫推了推眼镜，说碑文委托接了三个，但雕刻石只剩一块，后面两个要开工，材料可不够用。" },
      cvc_village_prep_rare: { name: "猫猫村稀材筹备", desc: "村委会这次张贴的是高价收购告示，说稀有材料库存全部告急，不拘哪种，一律收购。" },
      cvc_rare_combo: { name: "稀材联合委托", desc: "几家高端工坊联合发出委托，说库存核对下来各有短缺，带任意一组稀有材料来都算完成。" },
      cvc_village_grand_prep: { name: "猫猫村大典筹备", desc: "一年一度的猫猫村大典即将开幕，筹备组猫挨家挨户收集顶级材料，说用量很大，有多少要多少。" },
      cvc_moon_essence_secret: { name: "月光精华的秘密委托", desc: "神秘猫拉你进了巷角，压低声音说月光精华用途特殊，找了好几天都没找到，你若有，价格绝对满意。" },
      cvc_silkweed_fiber_guild: { name: "丝草坊的特供纤维", desc: "丝草坊的招牌是那件流光溢彩的展示品，老板猫说那种光泽只有丝草纤维才能做出来，最近原料告急。" },
      cvc_sun_resin_alchemist: { name: "炼金师的阳光树脂", desc: "炼金师猫对着满架子的烧瓶叹气，说阳光树脂是合成高级药剂的底料，但市面上的货几乎都被人包了。" },
      cvc_silkwood_vault: { name: "丝木工坊秘密特供", desc: "工坊主任猫关上门，说丝木是制作特级器具的材料，外面很难拿到，你若有货，这批报酬相当可观。" },
      cvc_gold_ore_treasury: { name: "金库的黄金矿石", desc: "金库管理猫拿着花名册，小声说近期的大笔兑换把储备金矿耗光了，急需补仓，这是最高等级的委托。" },
      cvc_goldvine_fiber_royal: { name: "金藤纤维的顶级委托", desc: "金丝绸坊的老板猫穿着华服等在门口，说金藤纤维是宫廷贡品的原料，能找到货的人凤毛麟角。" },
      cvc_moon_dew_mystery: { name: "月华之露的神秘订单", desc: "一张没有落款的委托纸夹在布告栏里，字迹工整写着：月华之露，重金求购，数量不限，报酬议。" },
      cvc_moonwood_legendary: { name: "月木大师的稀世订单", desc: "传说中的月木大师猫只在满月之夜出没，这次他留下了一张委托：月木一根，换以倾城之宝。" },
      cvc_base2_moss_spore_pharmacy: { name: "药铺要苔藓孢子", desc: "药铺老板猫戴着护目镜捣药，说森林苔藓孢子正是某个配方的关键原料，进货路被封了一周，谁能带来就收谁的。" },
      cvc_base2_cave_membrane_tannery: { name: "皮革坊要洞穴翼膜", desc: "皮革坊工匠猫捧着一叠样品，说洞穴蝙蝠的翼膜韧性极好，做出来的皮制品轻薄耐用，他连跑三趟森林都没摸到一只。" },
      cvc_base2_ruin_shard_museum: { name: "博物馆要遗迹碎核", desc: "博物馆馆长猫盯着空展柜叹气，说遗迹碎核是难得的历史遗存，是那段消逝文明的证明，送来一块便是一块。" },
      cvc_base2_dragon_scale_forge: { name: "锻造坊的龙鳞碎片", desc: "锻造坊铁匠猫夹着炉火说，只有熔岩巨龙的鳞片才能炼出那种特殊合金，龙鳞不好拿，他研究了这么多年只攒了几片。" },
      cvc_base2_forest_loot_combo: { name: "森林战利品综合收购", desc: "收购站今天同时缺几种森林材料，老板猫说苔藓孢子或洞穴翼膜都要，你有什么带什么，先到先得。" },
      cvc_base2_ruins_dragon_combo: { name: "遗迹与龙穴联合委托", desc: "联合工坊贴出双料委托，说遗迹碎核和龙鳞碎片同时告急，两样都是好材料，带来一批就开工。" },
      cvc_base3_frost_ledger_historian: { name: "学者要霜记账页", desc: "老学者猫坐在堆满卷宗的案台前说，霜记账页是雪原冰族留下的账册碎片，记载着远古贸易的痕迹，他花了半辈子还没集齐。" },
      cvc_base3_white_coin_mint: { name: "铸币坊要白币碎片", desc: "铸币坊主任猫翻着账本，说白币碎片精炼后能提升铸币导热性，这批委托数量大，报酬丰厚，今日有效。" },
      cvc_base3_snowseal_workshop: { name: "工艺坊要雪封蜡", desc: "工艺坊雕刻师猫擦了擦刀具，说雪封蜡是北地特有的封印材料，能保护精细雕刻免受湿气侵蚀，库存已经告急。" },
      cvc_base3_rimebone_forger: { name: "兵器大师要冰脊骨柄", desc: "兵器大师猫推开熔炉门，说冰脊骨柄来自雪原巨兽，握感绝佳又耐极寒，他做了一辈子兵器，只见过三根。" },
      cvc_base3_warm_thread_tailor: { name: "御寒工坊要暖丝核", desc: "御寒工坊裁缝猫扯着布料，说暖丝核藏在雪原兔毛深处，含天然保温成分，用它织出的衣物能抗极寒风雪。" },
      cvc_base3_snowfield_combo: { name: "雪原战利品综合委托", desc: "雪原远征队后勤猫贴出收购清单，说雪原材料一律收购，霜记账页、白币碎片、雪封蜡或冰算珠，带哪个都算完成今日委托。" },
      cvc_base4_shadow_silk_guild: { name: "暗影工坊要影之绸缎", desc: "暗影工坊裁缝猫压低嗓音说，影绸只有深渊影猫才能产，市面上根本找不到来路，你若有货，价格绝对让你满意。" },
      cvc_base4_shadow_orb_lab: { name: "魔法实验室要暗影球", desc: "实验室烧瓶里冒着黑雾，研究猫不抬头地说暗影球的能量浓度是任何人工材料都比不了的，没有它研究就推不下去。" },
      cvc_base4_phantom_claw_crafter: { name: "秘宝工匠要幻影鼠爪", desc: "秘宝工匠猫摊开图纸，悄悄说幻影鼠爪有特殊折光性，镶进器具后在暗处发幽光，他一直想找到这样的材料。" },
      cvc_base4_cursed_membrane_apothecary: { name: "诅咒翼膜的特殊收购", desc: "炼药师猫从帽沿下看了你一眼，说诅咒蝙蝠的翼膜提炼后有魔法抑制效果，委托方指定要这个，价格可以谈。" },
      cvc_base4_golem_core_engineer: { name: "工程师要傀儡暗核", desc: "机关工程师猫盯着图纸说，铁甲猫偶的暗核是最稳定的魔法动力源，他接的几批大机关订单全卡在材料上了。" },
      cvc_base4_abyss_combo: { name: "深渊素材联合委托", desc: "深渊探险工会贴出高价收购单，说深渊领主的核心或猫祖王的影玉，两样都急需，有货就来，报酬随材料结算。" },
      cvc_holy_cat_fur_weaver: { name: "神殿织工要祝福猫毛", desc: "神殿织工猫捧着一团发光绒毛，说圣猫侍祭的祝福毛是织造神圣披风的唯一原料，每逢典礼季节都供不应求。" },
      cvc_holy_cat_incense_ceremony: { name: "大典委员会要圣猫香炉", desc: "大典委员会主席猫拿着筹备清单，说圣猫香炉的香料已经见底，下个月三场神圣大典全靠这批，月底前必须备齐。" },
      cvc_holy_cat_medal_collector: { name: "守护勋章的秘密委托", desc: "一位行事神秘的收藏家猫把你拉到一边，说守护勋章每枚都有独特的封印纹路，他愿出高价，仅限今日收购。" },
      cvc_holy_cat_scroll_scholar: { name: "贤者学会的典籍收购", desc: "贤者学会首席学者猫站在书架旁，说猫贤者卷轴上记载着神殿秘法，每一份都是稀世孤本，学会愿以重金购入研究。" },
      cvc_holy_cat_jewel_treasury: { name: "神圣金库的王室宝石", desc: "神圣金库守门猫戴着白手套，说神圣猫王的王室宝石是最高信用担保物，金库正进行年度储备补仓，今日最高优先级委托。" },
      cvc_holy_cat_temple_combo: { name: "神殿素材综合收购", desc: "神殿后勤管理猫贴出收购公告，说典礼筹备各类物资同时告急，祝福猫毛、圣猫香炉、守护勋章，今日均高价收购。" },
      cvc_rumor_harmonic_lunar_loom_thread: { name: "传闻：月相织谱·备丝", desc: "织谱师猫说，月相织谱只在生活材料与战斗残响彼此贴合时显影。先送来树脂、纤维、祝福猫毛和影绸，它要试第一道底纹。" },
      cvc_rumor_harmonic_lunar_loom_pattern: { name: "传闻：月相织谱·定纹", desc: "底纹已经浮出细光。织谱师猫要更精纯的金藤纤维与辉核，再配上幻影爪和圣猫香炉，才敢继续推演。" },
      cvc_rumor_harmonic_lunar_loom_embryo: { name: "传闻：月相织谱·合辉", desc: "织谱边缘开始转动。晶石、月影纱、猫贤者卷轴和王室宝石会把整张织谱收束成一枚调和胚核。" },
      cvc_rumor_harmonic_shadow_echo_print: { name: "传闻：影爪回声·寻印", desc: "夜行记录员猫在墙边发现几枚浅浅爪印。它要用丝草纤维与纯净树脂托底，再以影爪丝和影绸描出回声轮廓。" },
      cvc_rumor_harmonic_shadow_echo_chord: { name: "传闻：影爪回声·调弦", desc: "爪印里传出细微振动。记录员猫要金藤纤维、白银、毒爪腺液和幻影爪来调弦，听清第二层节奏。" },
      cvc_rumor_harmonic_shadow_echo_embryo: { name: "传闻：影爪回声·定音", desc: "回声已经稳定。晶石与辉核能固定声形，镜爪碎片和影爪主印会让最后一声凝成调和胚核。" },
      cvc_rumor_harmonic_sacred_accord_seal: { name: "传闻：圣辉合约·封记", desc: "神殿抄写员猫取出一张空白金页，说封记要银、纯净树脂、祝福猫毛和影绸一同压住，字迹才不会散开。" },
      cvc_rumor_harmonic_sacred_accord_writ: { name: "传闻：圣辉合约·誊文", desc: "封记已经成形。抄写员猫要黄金、金藤纤维、圣猫香炉和守护勋章誊写正文，让每一行光纹都能被承住。" },
      cvc_rumor_harmonic_sacred_accord_embryo: { name: "传闻：圣辉合约·结辉", desc: "合约末尾只剩最后一笔。晶石、月影纱、猫贤者卷轴与王室宝石会把圣辉压成一枚调和胚核。" },
      cvc_b2_moss_bulk: { name: "苔藓孢子大批采购", desc: "大型药材商队在村口摆开收购台，说这批货要北运，量越大越好，孢子只要新鲜，价格按整批结算。" },
      cvc_b2_membrane_bulk: { name: "翼膜大宗收购令", desc: "皮具大商行开出收购令，说洞穴翼膜是高端皮货的核心材料，这次要的量很大，有多少收多少。" },
      cvc_b2_ruin_bulk: { name: "遗迹碎核研究专项", desc: "大学府的考古学系申请了专项经费，说要系统研究那批遗迹的材质，碎核越多研究越准确，全数收购。" },
      cvc_b2_dragon_bulk: { name: "龙鳞碎片顶级委托", desc: "皇家锻造坊秘密发出委托，说他们正在试制一种新合金，需要大量龙鳞碎片做实验，价格从优。" },
      cvc_b3_frost_bulk: { name: "霜记账页大规模征集", desc: "北地档案馆终于获得拨款，说要把所有散落的霜记账页系统归档，数量多多益善，今日敞开收购。" },
      cvc_b3_coin_bulk: { name: "白币碎片大宗收购", desc: "中央铸币局发布紧急采购令，说新批次高端铸币需要大量白币碎片作为基底材料，按重量结算。" },
      cvc_b3_rime_bulk: { name: "冰脊骨柄精英征购", desc: "北地兵器联盟公开招标，说要为精英部队定制一批冰脊柄兵器，骨柄越多越好，价格公道。" },
      cvc_b3_ice_bead_bulk: { name: "冰算珠高价征购", desc: "神秘机构发出高价委托，说冰算珠的运算特性令他们着迷，正在进行大规模测试，数量不限。" },
      cvc_b3_thread_bulk: { name: "暖丝核大批采购", desc: "极地御寒工坊接了大批订单，说今年冬天特别长，暖丝核供不应求，有多少全要。" },
      cvc_b4_silk_bulk: { name: "影绸大规模采购令", desc: "暗影工坊扩大产能，说影绸已经打入高端市场，原料跟不上了，大量采购，价格优惠。" },
      cvc_b4_orb_bulk: { name: "暗影球批量征购", desc: "魔法研究院批准了一个大型项目，需要大量暗影球做能量稳定性测试，今日开放大批采购。" },
      cvc_b4_claw_bulk: { name: "幻影爪大宗收购", desc: "秘宝公会发出大宗收购令，说幻影爪的折光特性正被用于新一代夜视器具的研发，需求量极大。" },
      cvc_b4_curse_bulk: { name: "诅咒翼膜批量收购", desc: "炼药师联盟联合采购，说诅咒翼膜精炼后的抑制剂供不应求，现开放大批收购，统一结算。" },
      cvc_b4_golem_bulk: { name: "傀儡暗核大规模征购", desc: "机关工坊联盟接了一批超级工程订单，核心动力源严重短缺，大量采购傀儡暗核，加急结算。" },
      cvc_b4_abyssal_bulk: { name: "深渊领主核心大批采购", desc: "深渊研究所开放大批次采购，说深渊核能量特性研究正处于关键阶段，数量越多越好。" },
      cvc_b4_jade_bulk: { name: "祖影玉大宗收购", desc: "神秘典藏馆的猫掌柜压低嗓子说，祖影玉是上古遗物，需求从来不减，今日大批次收购，价格从优。" },
      cvc_holy_fur_bulk: { name: "祝福猫毛圣典专供", desc: "神殿织造坊接了一批圣典专属披风的订单，织工猫说这种规模的订单三十年才一次，祝福猫毛必须大量备货。" },
      cvc_holy_incense_bulk: { name: "圣猫香炉大规模采购", desc: "年度大典筹备委员会提交了超大规模采购申请，说今年大典规模是史上最大，香炉数量必须翻倍。" },
      cvc_holy_medal_bulk: { name: "守护勋章典藏采购", desc: "皇家典藏馆正在筹备开国百年特展，说每位守护者的勋章都需要系统收录，今日最大规模采购。" },
      cvc_holy_scroll_bulk: { name: "贤者卷轴学术采购", desc: "跨国学术联盟申请专项经费，要建立一座完整的神殿典籍图书馆，贤者卷轴征集令正式发出。" },
      cvc_holy_jewel_bulk: { name: "王室宝石年度国库采购", desc: "神圣金库宣布年度大规模储备计划，说王室宝石是最高等级信用锚点，今年要大量储备。" },
      cvc_cross_b2b3_joint: { name: "森林×雪原联合委托", desc: "跨境商行同时在森林遗迹和极寒雪原进货，说两种材料配套使用效果更好，联合委托，一次完成。" },
      cvc_cross_b3b4_joint: { name: "雪原×深渊联合收购", desc: "神秘工坊的老板猫说，冰脊骨柄配上影绸才能做出最顶级的阴阳双材器具，缺一不可。" },
      cvc_cross_b4holy_joint: { name: "深渊×神殿联合委托", desc: "联合研究院的两位教授联名发出委托，一位研究暗影能量，一位研究神殿香炉，两种材料同时到货才能开工。" },
      cvc_cross_b2b4_joint: { name: "洞穴×暗影联合收购", desc: "特种皮具工坊说，洞穴翼膜配上影绸是制作隐形皮甲的绝配，联合采购，两样都不能少。" },
      cvc_cross_b3holy_joint: { name: "雪原×神殿联合委托", desc: "精品定制坊同时接了两种材料的订单，说白币碎片和祝福猫毛都是今天的紧缺料，一次送齐有奖励。" },
      cvc_cross_epic: { name: "全域史诗联合委托", desc: "传奇工匠猫发出了这辈子最大的一份委托，说他要打造一件集森林、雪原、深渊三域之力的神器，三种材料缺一不可。" },

      cvc_shadow_paw_footprints: { name: "【传闻】无声爪印", desc: "猫村调查员在夜里发现一串没有声音的爪印，委托你带来影爪丝与毒爪腺液，试着还原留下爪印的步法。" },
      cvc_shadow_paw_mirror_clue: { name: "【传闻】镜爪折光", desc: "拓本边缘出现了奇怪折光。调查员怀疑巢穴里有擅长镜像护身的精英，想用镜爪碎片确认路线。" },
      cvc_shadow_paw_master_trace: { name: "【传闻】追踪影爪头目", desc: "镜爪线索终于指向巢穴深处。带上头目印记，调查员会把完整路线和地图交给你。" },
      cvc_rumor_wolf_king_prequel: { name: "【传闻】深林里的嚎叫声", desc: "一位老猫猎人在村口张贴了一张皱巴巴的委托纸：「平原上近来有奇怪的狼毛散落，不像本地的狼。收集8根带来，我们一起研究研究。」" },
      cvc_rumor_wolf_king: { name: "【传闻】狼王的踪迹", desc: "老猎人看了你带来的线索碎片，沉默片刻后，从口袋里摸出一张模糊的照片递给你：「这是我多年前拍的，带着它去，碰见了你就知道了。」" },
      cvc_rumor_super_berry_bird: { name: "【传闻】浆果丛里的巨影", desc: "猫村布告栏上夹着一张皱巴巴的字条：「有人目击平原深处有个巨大身影在浆果丛中穿梭，愿出两万金币购买一颗超甜大浆果作引诱用，感兴趣的话来谈谈。」" },
      cvc_rumor_shadow_assassin_cat_prequel: { name: "【传闻】幽影迷踪", desc: "一位从喵影深渊侥幸归来的探险猫压低声音说：「深渊里有什么东西……它藏在影子里，我甚至没看清它的样子，但留下了奇怪的爪印。带来20根影之丝线，我给你讲个完整的故事。」" },
      cvc_rumor_shadow_assassin_cat: { name: "【传闻】影刺客猫召唤令", desc: "探险猫接过你带来的爪印拓本，仔细端详后眯起眼睛：「就是它。影刺客猫，深渊里最难缠的存在——因为你根本看不见它在哪里。这张召唤符或许能让它主动现身，但要做好最坏的打算。」" },
      cvc_rumor_glacial_phantom: { name: "【传闻】永冬之灵", desc: "一位从极寒雪原九死一生归来的探险者颤抖着说道：「那片雪原深处……有东西在等待。不是普通的猛兽，那是一种古老的灵魂——永冬之灵，万年前被封印于此，如今似乎正在苏醒。带来足够的雪原印记，我来帮你炼制召唤它的引灵符。」" },
      cvc_rumor_vow_eater_prequel: { name: "【传闻】五处熄灭的愿火", desc: "神殿司香猫发现祷墙上连续五处愿纹失去颜色，供香也总在天亮前化为紫灰。带来足量祝福猫毛、圣猫香与贤者卷轴，他会重铺祷墙、焚香校纹，再将五处空白愿纹完整拓下。" },
      cvc_rumor_vow_eater: { name: "【传闻】祷墙后的食愿声", desc: "拓片纸背浮出了整齐齿痕，祷墙后也传来缓慢咀嚼声。司香猫确认那是以未竟祈愿为食的烬貘；交出拓片，并以守护勋章、贤者卷轴与王室宝石封住五处愿口，他会把空愿扎成焦愿引香，让它在圣猫神殿深处现身。" },
      cvc_rumor_faceless_understudy_playbill: { name: "【传闻】闭园后的掌声", desc: "闭园后，空舞台上还会响起掌声。老道具师捡到一张涂花节目单，请你带些糖果炸弹、毛绒绒、瓶装星光和恶灵精华，看看墨团下面写过谁。" },
      cvc_rumor_faceless_understudy_invitation: { name: "【传闻】给空位的请柬", desc: "墨团下面没有名字。老道具师说，每晚都有人替这个空位演完整场。把节目单和他要的材料带来，他会做一张午夜请柬，把那位替演者请到台前。" }
    },
    rumor: {
      badge: "传闻",
      pityLabel: "保底进度"
    }
  }
